<script setup lang="ts">import type { PublishedGameSummary } from "@arcade/shared"; import FavoriteButton from "./FavoriteButton.vue"; import LaunchButton from "./LaunchButton.vue"; defineProps<{ games: PublishedGameSummary[]; favorite?: string[] }>(); const emit = defineEmits<{ favorite: [slug: string]; play: [slug: string] }>();</script><template><div class="featured-carousel"><article v-for="(game, index) in games.slice(0, 3)" :key="game.slug" class="featured-slide" :style="{ '--card-accent': game.accent ?? '#54d6ba' }"><div class="featured-glow"></div><div class="featured-content"><span class="portal-eyebrow">推荐作品 0{{ index + 1 }}</span><h2>{{ game.title }}</h2><p>{{ game.short_description }}</p><div class="featured-meta"><span>{{ game.categories[0]?.name }}</span><span>{{ game.input_modes.join(" / ") }}</span></div><LaunchButton :disabled="game.status !== 'published'" @launch="emit('play', game.slug)" /></div><FavoriteButton :active="favorite?.includes(game.slug) === true" :title="game.title" @toggle="emit('favorite', game.slug)" /></article></div></template>
